const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function bytes(value){const n=Number(value||0);if(n>=1073741824)return(n/1073741824).toFixed(2)+' GB';if(n>=1048576)return(n/1048576).toFixed(1)+' MB';if(n>=1024)return Math.round(n/1024)+' KB';return n+' B'}
function metric(index,value,tone='',note=''){const card=$('summary').children[index];card.className='metric '+tone;card.querySelector('b').textContent=value;card.querySelector('small')?.remove();if(note){const small=document.createElement('small');small.textContent=note;card.appendChild(small)}}
function healthCard(label,ok,detail){return`<div class="health ${ok?'ok':'fail'}"><span>${esc(label)}</span><b>${ok?'정상':'확인 필요'}</b>${detail?`<small>${esc(detail)}</small>`:''}</div>`}
function renderDatabase(db){const missing=db.indexes?.missing||[];$('database').innerHTML=`<div class="table-wrap"><table><thead><tr><th>구분</th><th>값</th><th>상태</th></tr></thead><tbody><tr><td>스키마 버전</td><td class="code">${esc(db.schema_version)}</td><td><span class="status ${db.schema_version==='0013'?'ok':'fail'}">${db.schema_version==='0013'?'최신':'업데이트 필요'}</span></td></tr><tr><td>고속 인덱스</td><td>${Number(db.indexes?.installed?.length||0)} / ${Number(db.indexes?.required?.length||0)}</td><td><span class="status ${db.fast_path_ready?'ok':'warn'}">${db.fast_path_ready?'정상':'일부 누락'}</span></td></tr><tr><td>승인 계정</td><td>${Number(db.rows?.approved_accounts||0).toLocaleString('ko-KR')}</td><td><span class="status ok">운영 중</span></td></tr><tr><td>평가 대상 / 항목</td><td>${Number(db.rows?.targets||0).toLocaleString('ko-KR')} / ${Number(db.rows?.target_items||0).toLocaleString('ko-KR')}</td><td><span class="status ok">확인</span></td></tr><tr><td>활성 파일</td><td>${Number(db.rows?.active_files||0).toLocaleString('ko-KR')} · ${bytes(db.active_file_bytes)}</td><td><span class="status ok">확인</span></td></tr></tbody></table></div>${missing.length?`<div class="issue">누락 인덱스: ${esc(missing.join(', '))}</div>`:''}`}
function renderRequests(rows){$('requests').innerHTML=rows.length?`<div class="list">${rows.map(r=>`<div class="row"><span class="status ${Number(r.status)>=500?'fail':Number(r.status)>=400?'warn':'ok'}">${esc(r.method)} ${Number(r.status)}</span><div><strong>${esc(r.path)}</strong><small>${esc(String(r.created_at||'').replace('T',' ').slice(0,19))}</small></div><span class="duration">${Number(r.duration_ms||0)} ms</span></div>`).join('')}</div>`:'<div class="empty">최근 요청 기록이 없습니다.</div>'}
function renderSlow(rows){$('slow').innerHTML=rows.length?`<div class="list">${rows.map(r=>`<div class="row"><span class="status ${Number(r.max_ms)>=1000?'fail':Number(r.max_ms)>=500?'warn':'ok'}">${Number(r.requests||0)}회</span><div><strong>${esc(r.path)}</strong><small>평균 ${Number(r.avg_ms||0)} ms</small></div><span class="duration">최대 ${Number(r.max_ms||0)} ms</span></div>`).join('')}</div>`:'<div class="empty">집계할 요청이 없습니다.</div>'}
async function load(){const button=$('refreshBtn');button.disabled=true;try{const [data,storage]=await Promise.all([window.EHSApi.request('/api/admin/system/summary',{ehsNoCache:true}),window.EHSApi.request('/api/admin/storage-status',{ehsNoCache:true})]);const d=data.diagnostics||{},db=data.database||{},req=data.requests||{},global=storage.storage?.global||{};metric(0,d.missing_tables?.length?'확인 필요':'정상',d.missing_tables?.length?'bad':'good',d.missing_tables?.length?`${d.missing_tables.length}개 테이블 누락`:'핵심 서비스 정상');metric(1,db.schema_version||'-',db.schema_version==='0013'?'good':'bad','현재 운영 D1');metric(2,String(req.errors_24h||0),Number(req.errors_24h)>0?'bad':'good','최근 24시간');metric(3,String(db.rows?.undetermined_items||0),Number(db.rows?.undetermined_items)>0?'warn':'good','N/A 판정 대기');metric(4,bytes(global.used_bytes),Number(global.percent)>=90?'bad':Number(global.percent)>=75?'warn':'good',`${Number(global.percent||0).toFixed(1)}% 사용`);$('generatedAt').textContent=new Date(data.generated_at).toLocaleString('ko-KR');$('health').innerHTML=`<div class="health-grid">${healthCard('Cloudflare D1',d.checks?.d1)}${healthCard('Cloudflare R2',d.checks?.r2)}${healthCard('정적 자산',d.checks?.assets)}${healthCard('성능 계측',d.checks?.analytics)}</div>${d.missing_tables?.length?`<div class="issue">누락 테이블: ${esc(d.missing_tables.join(', '))}</div>`:''}`;renderDatabase(db);renderRequests(req.recent||[]);renderSlow(req.slow_routes||[])}catch(error){const message=window.EHSApi?.describe?window.EHSApi.describe(error):error.message;['health','database','requests','slow'].forEach(id=>$(id).innerHTML=`<div class="error">${esc(message)}</div>`)}finally{button.disabled=false}}
$('refreshBtn').onclick=load;$('errorsBtn').onclick=async()=>{const box=$('requests');box.innerHTML='<div class="loading">오류 요청을 불러오는 중...</div>';try{const data=await window.EHSApi.request('/api/admin/system/requests?errors=1&limit=50',{ehsNoCache:true});renderRequests(data.requests||[])}catch(error){box.innerHTML=`<div class="error">${esc(error.message)}</div>`}};
(async()=>{try{const user=await window.EHSAuth.requireUser({role:'admin'});window.__EHS_PAGE_USER=user;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:user}));await load()}catch(error){if(error?.status!==401)document.body.innerHTML=`<main class="shell"><div class="error">${esc(error.message||'관리자 권한이 필요합니다.')}</div></main>`}})();
